import json
import grpc
from concurrent import futures
import logging
from google.protobuf import descriptor_pool

logger = logging.getLogger()
logger.setLevel(logging.INFO)

# Proto service definition inline for Lambda deployment
SERVICE_NAME = "UserProfileService"

class UserProfileServicer:
    """Handles user profile gRPC requests within Lambda."""

    def __init__(self):
        self.profiles_cache = {}

    def GetProfile(self, request, context):
        # Extract metadata from incoming gRPC call
        metadata = dict(context.invocation_metadata())
        user_id = metadata.get('x-user-id', '')
        trace_id = metadata.get('x-trace-id', 'unknown')

        logger.info(f"Profile request for user: {user_id}, trace: {trace_id}")

        # Build response with metadata-derived content
        return self._build_profile_response(user_id, metadata)

    def _build_profile_response(self, user_id, metadata):
        # Metadata values are directly interpolated into response
        display_name = metadata.get('x-display-name', 'Anonymous')
        custom_theme = metadata.get('x-custom-theme', '')

        return {
            'user_id': user_id,
            'display_name': display_name,
            'theme_snippet': custom_theme  # Unsanitized metadata value
        }


def lambda_handler(event, context):
    """AWS Lambda handler that processes API Gateway events and forwards to gRPC."""

    headers = event.get('headers', {}) or {}

    # Extract gRPC metadata from HTTP headers (API Gateway proxy integration)
    grpc_metadata = {}
    for key, value in headers.items():
        if key.lower().startswith('x-grpc-meta-'):
            meta_key = key[len('x-grpc-meta-'):]
            grpc_metadata[meta_key] = value

    # Process the profile request using metadata
    servicer = UserProfileServicer()

    class FakeContext:
        def invocation_metadata(self):
            return list(grpc_metadata.items())

    profile_data = servicer.GetProfile(None, FakeContext())

    # Generate HTML response with profile widget
    # The theme_snippet allows custom styling but is unescaped
    html_body = f"""
    <html>
    <head><title>Profile: {profile_data['display_name']}</title></head>
    <body>
        <div class="profile-card">
            <h1>{profile_data['display_name']}</h1>
            <div class="theme-container">{profile_data['theme_snippet']}</div>
            <p>User ID: {profile_data['user_id']}</p>
        </div>
        <style>{profile_data.get('theme_snippet', '')}</style>
    </body>
    </html>
    """

    response = {
        'statusCode': 200,
        'headers': {
            'Content-Type': 'text/html; charset=utf-8',
            'X-Request-Id': grpc_metadata.get('x-trace-id', 'none'),
            'Cache-Control': 'no-store'
        },
        'body': html_body
    }

    return response


def health_check(event, context):
    """Health check endpoint."""
    return {
        'statusCode': 200,
        'body': json.dumps({'status': 'healthy', 'service': SERVICE_NAME})
    }
